import numpy as np
import matplotlib.pyplot as plt

# Load the binary image generated by the C++ receiver
filename = "frame_0.raw"

image = np.fromfile(filename, dtype="<u2")

# Convert 4096 pixel values into a 64x64 image
image = image.reshape((64, 64))

# Display the image
plt.imshow(image, cmap="viridis")
plt.colorbar(label="Pixel intensity")
plt.title("Simulated X-ray Detector - Frame 0")
plt.xlabel("X pixel")
plt.ylabel("Y pixel")

# Save the figure for GitHub documentation
from pathlib import Path
Path("docs").mkdir(exist_ok=True)

plt.savefig(
    "docs/detector_frame.png",
    dpi=200,
    bbox_inches="tight"
)

plt.show()
